        push(node, node_l, node_r)
        if r < node_l or node_r < l:
            return
        if l <= node_l and node_r <= r:
            lazy[node] += val
            push(node, node_l, node_r)
            return
        mid = (node_l + node_r) // 2
        update_range(l, r, val, 2*node, node_l, mid)
        update_range(l, r, val, 2*node+1, mid+1, node_r)
        st[node] = max(st[2*node], st[2*node+1])

    def query_max(l, r, node=1, node_l=1, node_r=N):
        push(node, node_l, node_r)
        if r < node_l or node_r < l:
            return 0
        if l <= node_l and node_r <= r:
            return st[node]
        mid = (node_l + node_r) // 2
        return max(query_max(l, r, 2*node, node_l, mid),
                   query_max(l, r, 2*node+1, mid+1, node_r))

    def lca(u, v):
        while head[u] != head[v]:
            if depth[head[u]] > depth[head[v]]:
                u = parent[head[u]]
            else:
                v = parent[head[v]]
        return u if depth[u] < depth[v] else v

    def distance(u, v):
        anc = lca(u, v)
        return depth[u] + depth[v] - 2*depth[anc]

    for _ in range(Q):
        a, b = map(int, sys.stdin.readline().split())
        print(distance(a, b))

